// Initialize the daily ops pipeline
// Sequential chain follows — each fetch passes through to the next
return [{ json: { trigger: true, timestamp: new Date().toISOString() } }];

// Use named references to get data from each upstream node
const projectsData = $('Fetch Active Projects').first().json;
const scriptsData = $('Fetch Pending Scripts').first().json;
const leadsData = $('Fetch Due Follow-ups').first().json;
const invoicesData = $('Fetch Overdue Invoices').first().json;
const eventsData = $('Fetch Recent Events').first().json;

// ClickUp data
let clickupTeams = [];
let clickupTasks = [];
try {
  clickupTeams = $('Fetch ClickUp Teams').first().json.teams || [];
  clickupTasks = ($('Fetch ClickUp Tasks').first().json.tasks || []);
} catch(e) {
  // ClickUp fetch may fail - continue without it
}

const projects = (projectsData.records || []).map(r => ({ id: r.id, ...r.fields }));
const scripts = (scriptsData.records || []).map(r => ({ id: r.id, ...r.fields }));
const leads = (leadsData.records || []).map(r => ({ id: r.id, ...r.fields }));
const invoices = (invoicesData.records || []).map(r => ({ id: r.id, ...r.fields }));
const events = (eventsData.records || []).map(r => ({ id: r.id, ...r.fields }));

const now = new Date();
const todayStr = now.toISOString().split('T')[0];

// Detect stuck projects (status unchanged for > 2 days)
const stuckProjects = projects.filter(p => {
  const lastUpdate = p.updated_at || p.created_at;
  if (!lastUpdate) return false;
  const days = (now - new Date(lastUpdate)) / (1000 * 60 * 60 * 24);
  return days > 2;
});

// Group projects by status
const projectsByStatus = {};
for (const p of projects) {
  const s = p.status || 'Unknown';
  projectsByStatus[s] = (projectsByStatus[s] || 0) + 1;
}

// Group scripts by status
const scriptsByStatus = {};
for (const s of scripts) {
  const st = s.status || 'Unknown';
  scriptsByStatus[st] = (scriptsByStatus[st] || 0) + 1;
}

// Summarize events by type
const eventsByType = {};
const escalations = [];
const phaseTransitions = [];
const campaignAlerts = [];
const leadActions = [];
for (const e of events) {
  const t = e.event_type || 'unknown';
  eventsByType[t] = (eventsByType[t] || 0) + 1;

  if (t === 'escalation' || t === 'sla_breach' || (e.severity && e.severity === 'high')) {
    escalations.push({ type: t, brand: e.brand_name || e.project_id, detail: e.detail || e.message || '', agent: e.agent_name || '' });
  }
  if (t === 'phase_complete' || t === 'phase_triggered' || t === 'workflow_complete') {
    phaseTransitions.push({ type: t, brand: e.brand_name || e.project_id, detail: e.detail || e.message || '', agent: e.agent_name || '' });
  }
  if (t === 'campaign_alert' || t === 'ad_performance' || t === 'budget_alert') {
    campaignAlerts.push({ type: t, brand: e.brand_name, detail: e.detail || e.message || '' });
  }
  if (t === 'lead_action' || t === 'new_lead' || t === 'proposal_sent') {
    leadActions.push({ type: t, company: e.company_name || e.lead_name, detail: e.detail || e.message || '' });
  }
}

// Process ClickUp tasks
const overdueTasks = [];
const todayTasks = [];
const inProgressTasks = [];
const clickupByStatus = {};

for (const task of clickupTasks) {
  const status = (task.status && task.status.status) || 'unknown';
  clickupByStatus[status] = (clickupByStatus[status] || 0) + 1;

  // Check due date
  if (task.due_date) {
    const dueDate = new Date(parseInt(task.due_date));
    const dueDateStr = dueDate.toISOString().split('T')[0];

    if (dueDate < now && status !== 'closed' && status !== 'complete') {
      overdueTasks.push({
        name: task.name,
        status: status,
        due: dueDateStr,
        assignees: (task.assignees || []).map(a => a.username || a.email).join(', '),
        list: task.list ? task.list.name : '',
        priority: task.priority ? task.priority.priority : 'none',
        url: task.url || ''
      });
    } else if (dueDateStr === todayStr) {
      todayTasks.push({
        name: task.name,
        status: status,
        assignees: (task.assignees || []).map(a => a.username || a.email).join(', '),
        list: task.list ? task.list.name : '',
        priority: task.priority ? task.priority.priority : 'none',
        url: task.url || ''
      });
    }
  }

  if (status === 'in progress' || status === 'in review') {
    inProgressTasks.push({
      name: task.name,
      status: status,
      assignees: (task.assignees || []).map(a => a.username || a.email).join(', '),
      list: task.list ? task.list.name : '',
      due: task.due_date ? new Date(parseInt(task.due_date)).toISOString().split('T')[0] : 'none',
      priority: task.priority ? task.priority.priority : 'none'
    });
  }
}

// Capacity
const MAX_CAPACITY = 15;
const available = Math.max(0, MAX_CAPACITY - projects.length);

const briefingData = {
  date: todayStr,
  active_projects: projects.length,
  projects_by_status: projectsByStatus,
  stuck_projects: stuckProjects.map(p => ({ brand: p.brand_name, code: p.client_code, status: p.status })),
  pending_scripts: scripts.length,
  scripts_by_status: scriptsByStatus,
  scripts_awaiting_review: scripts.filter(s => s.status === 'In Review' || s.status === 'Client Review').map(s => ({ title: s.script_title, brand: s.brand_name, status: s.status })),
  leads_to_follow_up: leads.map(l => ({ company: l.company_name, contact: l.contact_name, stage: l.stage, follow_up: l.next_follow_up })),
  overdue_invoices: invoices.map(i => ({ number: i.invoice_number, amount: i.amount, due: i.due_date })),
  capacity: { current: projects.length, max: MAX_CAPACITY, available },
  agent_events: {
    total_events: events.length,
    events_by_type: eventsByType,
    escalations,
    phase_transitions: phaseTransitions,
    campaign_alerts: campaignAlerts,
    lead_actions: leadActions
  },
  clickup: {
    total_tasks: clickupTasks.length,
    tasks_by_status: clickupByStatus,
    overdue_tasks: overdueTasks,
    due_today: todayTasks,
    in_progress: inProgressTasks,
    workspace: clickupTeams.length > 0 ? clickupTeams[0].name : 'N/A'
  }
};

return [{ json: briefingData }];

const response = $input.first().json;
const aggregatedData = $('Aggregate All Data').first().json;

// Check for Gemini errors
const hasError = response.error || response.statusCode >= 400 || !response.candidates;

let briefing;
if (!hasError) {
  briefing = response.candidates?.[0]?.content?.parts?.[0]?.text;
}

if (!briefing) {
  // Fallback: build plain-text briefing from raw aggregated data
  const d = aggregatedData;
  const lines = [];
  lines.push('*Daily Operations Briefing \u2014 ' + (d.date || new Date().toISOString().split('T')[0]) + '*');
  lines.push('_(Gemini unavailable \u2014 auto-generated fallback)_\n');

  // Priority actions
  lines.push('*Priority Actions:*');
  if (d.clickup?.overdue_tasks?.length > 0) {
    for (const t of d.clickup.overdue_tasks) {
      lines.push('\u2022 OVERDUE TASK: ' + t.name + ' (due ' + t.due + ') \u2014 ' + t.assignees);
    }
  }
  if (d.stuck_projects && d.stuck_projects.length > 0) {
    for (const p of d.stuck_projects) {
      lines.push('\u2022 STUCK: ' + p.brand + ' (' + p.code + ') \u2014 ' + p.status);
    }
  }
  if (d.agent_events?.escalations?.length > 0) {
    for (const e of d.agent_events.escalations) {
      lines.push('\u2022 ESCALATION: ' + e.brand + ' \u2014 ' + e.detail);
    }
  }
  if ((!d.clickup?.overdue_tasks || d.clickup.overdue_tasks.length === 0) && d.stuck_projects?.length === 0 && (!d.agent_events?.escalations || d.agent_events.escalations.length === 0)) {
    lines.push('\u2022 No urgent items');
  }

  // Pipeline
  lines.push('\n*Pipeline Status (' + d.active_projects + ' active):*');
  for (const [status, count] of Object.entries(d.projects_by_status || {})) {
    lines.push('\u2022 ' + status + ': ' + count);
  }

  // Scripts
  lines.push('\n*Scripts (' + d.pending_scripts + ' pending):*');
  for (const [status, count] of Object.entries(d.scripts_by_status || {})) {
    lines.push('\u2022 ' + status + ': ' + count);
  }

  // ClickUp
  if (d.clickup) {
    lines.push('\n*ClickUp Tasks (' + d.clickup.total_tasks + ' total):*');
    if (d.clickup.due_today?.length > 0) {
      lines.push('Due today:');
      for (const t of d.clickup.due_today) {
        lines.push('\u2022 ' + t.name + ' (' + t.status + ') \u2014 ' + t.assignees);
      }
    }
    if (d.clickup.in_progress?.length > 0) {
      lines.push('In progress:');
      for (const t of d.clickup.in_progress.slice(0, 5)) {
        lines.push('\u2022 ' + t.name + ' (due ' + t.due + ') \u2014 ' + t.assignees);
      }
    }
  }

  // Leads
  if (d.leads_to_follow_up?.length > 0) {
    lines.push('\n*Leads Due (' + d.leads_to_follow_up.length + '):*');
    for (const l of d.leads_to_follow_up.slice(0, 5)) {
      lines.push('\u2022 ' + l.company + ' (' + l.stage + ') \u2014 follow up: ' + l.follow_up);
    }
  }

  // Invoices
  if (d.overdue_invoices?.length > 0) {
    lines.push('\n*Overdue Invoices (' + d.overdue_invoices.length + '):*');
    for (const i of d.overdue_invoices) {
      lines.push('\u2022 ' + i.number + ' \u2014 ' + i.amount);
    }
  }

  // Capacity
  lines.push('\n*Capacity:* ' + d.capacity?.current + '/' + d.capacity?.max + ' (' + d.capacity?.available + ' available)');

  briefing = lines.join('\n');
}

const _geminiError = hasError ? (response.error || response.statusMessage || 'No candidates in response') : null;
return [{ json: { briefing, _geminiError } }];

// Check if Gemini or Slack had errors and log them
const parsedData = $('Parse Briefing').first().json;
const slackResult = $input.first().json;

const errors = [];
if (parsedData._geminiError) {
  errors.push('Gemini: ' + parsedData._geminiError);
}
if (slackResult.error || slackResult.statusCode >= 400) {
  errors.push('Slack: ' + (slackResult.error || slackResult.statusMessage || 'HTTP ' + slackResult.statusCode));
}

if (errors.length === 0) return [];

return [{ json: {
  records: [{
    fields: {
      agent: 'daily_ops',
      event_type: 'system_error',
      severity: 'high',
      message: 'Daily Ops errors: ' + errors.join('; '),
      payload: JSON.stringify({ errors, timestamp: new Date().toISOString() }),
      created_at: new Date().toISOString()
    }
  }]
} }];
